/** Endpoints under `/api/v1/sequencenumber`. */
export class SequencenumberResource {
  readonly #http: CashCtrlHttp;

  constructor(http: CashCtrlHttp) {
    this.#http = http;
  }

  /**
   * Create sequence number
   * Creates a new sequence number. Note that you cannot assign the sequence
   * number to a type (e.g. Journal) here, this is done in the Settings or in
   * the corresponding category (e.g. Order category ). Returns either a
   * success or multiple error messages (for each issue).
   * `POST /api/v1/sequencenumber/create.json`
   * @see
   * https://app.cashctrl.com/static/help/en/api/index.html#/sequencenumber/create.json
   */
  create(params: M.SequencenumberCreateParams, signal?: AbortSignal): Promise<WriteEnvelope> {
    return this.#http.post<WriteEnvelope>("/api/v1/sequencenumber/create.json", params, signal);
  }

  /**
   * Delete sequence number
   * Deletes one or multiple sequence numbers. Only unused sequence numbers can
   * be deleted. Returns either a success or error message.
   * `POST /api/v1/sequencenumber/delete.json`
   * @see
   * https://app.cashctrl.com/static/help/en/api/index.html#/sequencenumber/delete.json
   */
  delete_(params: M.SequencenumberDeleteParams, signal?: AbortSignal): Promise<WriteEnvelope> {
    return this.#http.post<WriteEnvelope>("/api/v1/sequencenumber/delete.json", params, signal);
  }

  /**
   * Get generated number
   * Returns the next generated number for the given ID or type and optionally
   * category.
   * `GET /api/v1/sequencenumber/get`
   * @see
   * https://app.cashctrl.com/static/help/en/api/index.html#/sequencenumber/get
   */
  get(params: M.SequencenumberGetParams, signal?: AbortSignal): Promise<unknown> {
    return this.#http.get<unknown>("/api/v1/sequencenumber/get", params, signal);
  }

  /**
   * List sequence numbers
   * `GET /api/v1/sequencenumber/list.json`
   * @see
   * https://app.cashctrl.com/static/help/en/api/index.html#/sequencenumber/list.json
   */
  list(params?: Record<string, never>, signal?: AbortSignal): Promise<M.Sequencenumber[]> {
    return this.#http.list<M.Sequencenumber>("/api/v1/sequencenumber/list.json", undefined, signal);
  }

  /**
   * Read sequence number
   * Returns a single sequence number by ID or type and optionally category.
   * `GET /api/v1/sequencenumber/read.json`
   * @see
   * https://app.cashctrl.com/static/help/en/api/index.html#/sequencenumber/read.json
   */
  async read(params: M.SequencenumberReadParams, signal?: AbortSignal): Promise<M.Sequencenumber> {
    return (await this.#http.get<{ data: M.Sequencenumber }>("/api/v1/sequencenumber/read.json", params, signal)).data;
  }

  /**
   * Update sequence number
   * Updates an existing sequence number. Note that all parameters must be
   * submitted, omitted parameters are treated as empty values. Returns either
   * a success or multiple error messages (for each issue).
   * `POST /api/v1/sequencenumber/update.json`
   * @see
   * https://app.cashctrl.com/static/help/en/api/index.html#/sequencenumber/update.json
   */
  update(params: M.SequencenumberUpdateParams, signal?: AbortSignal): Promise<WriteEnvelope> {
    return this.#http.post<WriteEnvelope>("/api/v1/sequencenumber/update.json", params, signal);
  }
}

